{
  "avaliacoes": [
    {
      "id": "E28a0d8db9652cff9",
      "pertinente": true,
      "tipo": "explicacao_tecnica",
      "achados": [
        {
          "proposicao": "Em modo de offloading, o sistema de gás inerte pode ser usado para manter a pressão nos tanques de carga, e a conexão com o navio aliviador pode permitir proteger simultaneamente os tanques de óleo cru do FPSO e do shuttle tanker sem perda de hidrocarbonetos ou VOCs durante a operação normal descrita.",
          "trechos": [
            "E28a0d8db9652cff9:0:698"
          ],
          "condicoes": [
            "modo de offloading",
            "volumes elevados requeridos",
            "conexão entre FPSO e shuttle tanker"
          ],
          "limites": [
            "o trecho descreve a operação normal do sistema, não cobre todas as condições anormais",
            "ainda pode ser necessária inspeção dos tanques do FPSO"
          ]
        },
        {
          "proposicao": "Para viabilizar gas freeing de tanques após armazenamento de óleo cru, é requerido gerador de gás inerte, e o gás inerte é usado para deslocar vapores de hidrocarbonetos mantendo o teor de oxigênio abaixo do limite explosivo dos hidrocarbonetos antes da purga com ar.",
          "trechos": [
            "E28a0d8db9652cff9:0:698",
            "E28a0d8db9652cff9:698:1391"
          ],
          "condicoes": [
            "tanque previamente usado para armazenamento de óleo cru",
            "necessidade de inspeção e gas freeing"
          ],
          "limites": [
            "o texto não detalha projeto do gerador nem parâmetros completos de operação",
            "a expressão sobre limite explosivo é apresentada no contexto do documento e não como critério normativo brasileiro"
          ]
        },
        {
          "proposicao": "Antes da entrada em tanque que transportou óleo cru, a atmosfera deve ser verificada como segura; durante tank washing, se o O2 exceder 8%, a lavagem deve ser interrompida até estabilização em 8% O2 ou menos.",
          "trechos": [
            "E28a0d8db9652cff9:698:1391",
            "E28a0d8db9652cff9:1391:2053"
          ],
          "condicoes": [
            "entrada em tanque anteriormente usado para óleo cru",
            "execução de tank washing"
          ],
          "limites": [
            "o valor de 8% aparece como critério do documento-fonte, não foi convertido em requisito geral fora desse contexto",
            "o trecho não esgota outros contaminantes ou verificações necessárias para entrada"
          ]
        }
      ]
    },
    {
      "id": "Ee1712ea9088cf636",
      "pertinente": true,
      "tipo": "recomendacao",
      "achados": [
        {
          "proposicao": "Em isolamentos relevantes de tanques, é recomendado o uso de DBB ou spools removíveis como parte de sistemas seguros de trabalho.",
          "trechos": [
            "Ee1712ea9088cf636:0:697"
          ],
          "condicoes": [
            "tarefas de isolamento de tanques relevantes"
          ],
          "limites": [
            "trata-se de recomendação, não de obrigação universal",
            "o texto não compara desempenho com outras soluções de isolamento"
          ]
        },
        {
          "proposicao": "Operações com cabeçalhos de ventilação e gás inerte exigem sistemas seguros de trabalho para garantir alinhamento correto do vaso e suprimento positivo de gás inerte ao vaso durante crude oil washing.",
          "trechos": [
            "Ee1712ea9088cf636:697:1392"
          ],
          "condicoes": [
            "crude oil washing como operação rotineira",
            "existência de sistema de cabeçalhos de IG"
          ],
          "limites": [
            "o trecho não define critérios instrumentados específicos para confirmar alinhamento ou vazão",
            "não descreve resposta detalhada a falhas de suprimento"
          ]
        },
        {
          "proposicao": "O documento distingue funções de diferentes cabeçalhos associados ao gás inerte: clean inert gas header para inertização inicial de tanques gas free antes da introdução de óleo, dirty inert gas header para ventilar IG durante carregamento e preencher os tanques com IG durante offloading e crude oil washing, e crude oil tank purge header para operações de inertização inicial e gas freeing.",
          "trechos": [
            "Ee1712ea9088cf636:0:697",
            "Ee1712ea9088cf636:697:1392"
          ],
          "condicoes": [
            "existência de vários cabeçalhos de ventilação/IG no sistema"
          ],
          "limites": [
            "a descrição é funcional e não cobre arranjos alternativos de projeto",
            "não informa limites de pressão, vazão ou composição"
          ]
        }
      ]
    },
    {
      "id": "Eb09f8ac2af6ec76e",
      "pertinente": true,
      "tipo": "explicacao_tecnica",
      "achados": [
        {
          "proposicao": "FPSOs e FSUs monohull acumulam riscos de integridade marítima e riscos associados ao carregamento, armazenamento e descarga de óleo cru; por isso, estabilidade, integridade estanque e manutenção de posição requerem controle rigoroso.",
          "trechos": [
            "Eb09f8ac2af6ec76e:0:698"
          ],
          "condicoes": [
            "operações de carregamento, armazenamento e descarga de óleo cru em FPSO/FSU"
          ],
          "limites": [
            "o trecho é introdutório e não detalha critérios quantitativos de controle"
          ]
        },
        {
          "proposicao": "Para evitar que a atmosfera no tanque de óleo cru entre na faixa explosiva, é necessário controle rigoroso dos sistemas de inertização durante carregamento e descarga, e operações de tank washing, purga e gas freeing para preparação de entrada em tanque devem seguir procedimento.",
          "trechos": [
            "Eb09f8ac2af6ec76e:698:1395"
          ],
          "condicoes": [
            "tanques de óleo cru em operação ou sendo preparados para entrada"
          ],
          "limites": [
            "o trecho afirma necessidade de controle e procedimento, mas não especifica a sequência completa nem todos os parâmetros de aceitação"
          ]
        },
        {
          "proposicao": "Perda de posição de FPSO/FSU pode levar a colisão com instalação adjacente ou liberação de hidrocarbonetos por fratura de risers de perfuração ou operação de poços; por isso, o sistema de amarração, equipamentos e arranjos são tratados como elementos críticos de segurança no contexto do safety case descrito.",
          "trechos": [
            "Eb09f8ac2af6ec76e:1395:2089"
          ],
          "condicoes": [
            "perda de posição da unidade"
          ],
          "limites": [
            "o enquadramento como safety case e SCE pertence ao contexto regulatório citado no documento",
            "a relação é relevante ao recorte por interface com segurança dos tanques, mas não trata diretamente de dosagem, purga ou qualidade do IG"
          ]
        }
      ]
    },
    {
      "id": "Eb7b63a255a73db0c",
      "pertinente": true,
      "tipo": "explicacao_tecnica",
      "achados": [
        {
          "proposicao": "Após tank washing de tanque que transportou óleo cru, deve-se purgar a atmosfera com gás inerte até demonstrar teor de hidrocarbonetos de 2% ou menos, para que a etapa subsequente de gas freeing não leve parte da atmosfera do tanque à faixa inflamável.",
          "trechos": [
            "Eb7b63a255a73db0c:0:700"
          ],
          "condicoes": [
            "tanque usado para transporte/armazenamento de óleo cru",
            "tank washing previamente realizado"
          ],
          "limites": [
            "o valor de 2% decorre deste documento e contexto operacional específico",
            "o trecho não especifica método analítico nem base de medição"
          ]
        },
        {
          "proposicao": "Gas freeing extensivo com ar fresco, após a purga com gás inerte, permite alcançar condições seguras para entrada sem que a atmosfera do tanque passe pela faixa inflamável, conforme a sequência operacional descrita.",
          "trechos": [
            "Eb7b63a255a73db0c:0:700",
            "Eb7b63a255a73db0c:700:1400"
          ],
          "condicoes": [
            "purga prévia com gás inerte concluída",
            "teor de hidrocarbonetos previamente demonstrado em 2% ou menos"
          ],
          "limites": [
            "o trecho descreve a lógica da sequência, não garante segurança sem outras verificações",
            "não detalha tempos, vazões ou arranjos de ventilação"
          ]
        },
        {
          "proposicao": "Para entrada em tanque, deve haver avaliação de risco e testes de gás compatíveis com os contaminantes razoavelmente esperados, considerando carga anterior, ventilação do espaço, estrutura do tanque, revestimentos e outros fatores relevantes; em tanques de lastro ou espaços vazios adjacentes a tanque de carga ou bunker, é prudente testar vapores de carga, deficiência de oxigênio e gases tóxicos.",
          "trechos": [
            "Eb7b63a255a73db0c:700:1400"
          ],
          "condicoes": [
            "preparação para entrada em espaço confinado",
            "especialmente em tanque de lastro ou void space adjacente a tanque de carga ou bunker"
          ],
          "limites": [
            "o documento usa 'é prudente', caracterizando orientação e não obrigação universal",
            "não enumera lista fechada de contaminantes"
          ]
        }
      ]
    },
    {
      "id": "Eaf4ebcf6cf6a0eca",
      "pertinente": true,
      "tipo": "recomendacao",
      "achados": [
        {
          "proposicao": "Na inspeção do sistema de gás inerte, deve-se confirmar o teor de oxigênio associado ao sistema e verificar se os alarmes estão ajustados em níveis apropriados, além de confirmar a resposta operacional prevista para teor elevado de oxigênio na corrente de gás inerte.",
          "trechos": [
            "Eaf4ebcf6cf6a0eca:0:698"
          ],
          "condicoes": [
            "atividade de inspeção/avaliação do sistema de IG"
          ],
          "limites": [
            "o trecho não informa setpoints numéricos dos alarmes",
            "o documento trata de verificação inspetiva, não de critério brasileiro mandatório"
          ]
        },
        {
          "proposicao": "Crude oil washing em tanques de armazenamento é apresentado como mandatório para conformidade com a MARPOL 73/78, Regulamento 13, e envolve recirculação de óleo cru seco ao tanque por bicos de aspersão durante offloading; a frequência pode ser a cada offloading ou reduzida.",
          "trechos": [
            "Eaf4ebcf6cf6a0eca:698:1396"
          ],
          "condicoes": [
            "contexto de conformidade com a convenção internacional citada",
            "durante operações de offloading"
          ],
          "limites": [
            "trata-se de referência a norma/convenção internacional, não convertida aqui em requisito brasileiro",
            "a frequência é apresentada como variável"
          ]
        },
        {
          "proposicao": "O detentor da instalação deve assegurar sistemas para prevenir formação de atmosfera inflamável nos tanques de armazenamento, especialmente a partir de isolamentos de processo incorretos em operações simultâneas; essas atividades são intensivas em operador e requerem sistemas seguros de trabalho estritos, sendo recomendado DBB ou spools removíveis nos isolamentos pertinentes.",
          "trechos": [
            "Eaf4ebcf6cf6a0eca:1396:2095"
          ],
          "condicoes": [
            "operações simultâneas em tanques de armazenamento",
            "risco de isolamentos incorretos"
          ],
          "limites": [
            "parte do conteúdo é recomendação e parte é formulação de dever do operador no contexto do documento",
            "não detalha como validar a eficácia de cada isolamento"
          ]
        }
      ]
    },
    {
      "id": "E9217de1f8cc10e3a",
      "pertinente": true,
      "tipo": "explicacao_tecnica",
      "achados": [
        {
          "proposicao": "O sistema de ventilação de um FPSO exige consideração adicional em comparação a um petroleiro convencional, porque a unidade permanece essencialmente fixa e, em tempo calmo, há menor movimento para dispersar vapores ventilados; isso aumenta a probabilidade de formação de atmosferas inflamáveis ao redor das saídas de ventilação.",
          "trechos": [
            "E9217de1f8cc10e3a:0:700"
          ],
          "condicoes": [
            "FPSO essencialmente fixo",
            "tempo calmo",
            "descarga de vapores pelo sistema de ventilação"
          ],
          "limites": [
            "a comparação é contextual e qualitativa",
            "o trecho não quantifica dispersão nem distâncias seguras"
          ]
        },
        {
          "proposicao": "O blanketing por hidrocarboneto é descrito como alternativa fechada ao uso de gás inerte nos tanques do FPSO, desde que o campo produza gás suficiente para operar o sistema; o gás puro de hidrocarboneto atua como blanket gas para impedir a intrusão de oxigênio na atmosfera do tanque e recuperar o off-gas.",
          "trechos": [
            "E9217de1f8cc10e3a:700:1396"
          ],
          "condicoes": [
            "campo com produção de gás suficiente para operar o sistema"
          ],
          "limites": [
            "é apresentado como alternativa técnica, não como solução universal",
            "o trecho não discute compatibilidade com todos os cenários operacionais"
          ]
        },
        {
          "proposicao": "No modo de carregamento, o gás excedente do tanque de carga pode ser recuperado e reciclado ao processo; no offloading, devido aos grandes volumes, é provável o uso de sistema de gás inerte para manter a pressão nos tanques. O sistema fechado elimina emissões à atmosfera durante operação normal, mas os tanques ainda precisam ser inspecionados.",
          "trechos": [
            "E9217de1f8cc10e3a:1396:2077"
          ],
          "condicoes": [
            "modo de loading para reciclo de gás excedente",
            "modo de offloading com grandes volumes",
            "operação normal do sistema fechado"
          ],
          "limites": [
            "o próprio trecho indica probabilidade de uso de IG no offloading, não certeza em todos os casos",
            "a necessidade de inspeção mantém a exigência de operações posteriores de preparação do tanque"
          ]
        }
      ]
    }
  ],
  "concluir": false,
